(()=>{const names=["webkitAnimation", "webkitBorderAfter", "webkitBorderBefore", "webkitBorderEnd", "webkitBorderRadius", "webkitBorderStart", "webkitColumnRule", "webkitColumns", "webkitFlex", "webkitFlexFlow", "webkitMask", "webkitMaskBoxImage", "webkitMaskPosition", "webkitTextEmphasis", "webkitTextStroke", "webkitTransition"];const out={};for(const name of names){out[name]={};for(const value of ['initial','inherit','unset','revert','revert-layer','var(--choice)']){const s=document.createElement('div').style;s[name]=value;const css=name.replace(/[A-Z]/g,c=>'-'+c.toLowerCase()).replace(/^webkit-/,'-webkit-');out[name][value]={text:s.cssText,value:s[name],components:Array.from({length:s.length},(_,i)=>{const key=s.item(i);return [key,s.getPropertyValue(key)]}),removed:s.removeProperty(css),empty:s.cssText};}}return out})()
